import{_ as i,c as a,o as e,ag as o}from"./chunks/framework.B1jFR3yW.js";const _=JSON.parse('{"title":"数据库","description":"","frontmatter":{},"headers":[],"relativePath":"计划/计算机基础/数据库.md","filePath":"计划/计算机基础/数据库.md"}'),r={name:"计划/计算机基础/数据库.md"};function t(d,l,u,h,c,n){return e(),a("div",null,[...l[0]||(l[0]=[o('<h1 id="数据库" tabindex="-1">数据库 <a class="header-anchor" href="#数据库" aria-label="Permalink to &quot;数据库&quot;">​</a></h1><blockquote><p>对个人开发者来说，数据库不是“会连上就行”，而是要能设计数据、写对查询、控制性能、保证数据安全。</p></blockquote><h2 id="你需要掌握什么" tabindex="-1">你需要掌握什么 <a class="header-anchor" href="#你需要掌握什么" aria-label="Permalink to &quot;你需要掌握什么&quot;">​</a></h2><h3 id="_1-关系型数据库基础" tabindex="-1">1. 关系型数据库基础 <a class="header-anchor" href="#_1-关系型数据库基础" aria-label="Permalink to &quot;1. 关系型数据库基础&quot;">​</a></h3><ul><li>表、行、列的概念</li><li>主键、外键、唯一约束、非空约束</li><li>一对一、一对多、多对多的建模方式</li><li>范式的基本思想，不必死记，但要理解“避免冗余和异常更新”</li></ul><p>至少要能做到：</p><ul><li>为用户、订单、文章、评论、订阅等业务设计基础表结构</li></ul><h3 id="_2-sql-能力" tabindex="-1">2. SQL 能力 <a class="header-anchor" href="#_2-sql-能力" aria-label="Permalink to &quot;2. SQL 能力&quot;">​</a></h3><ul><li><code>select</code>、<code>insert</code>、<code>update</code>、<code>delete</code></li><li><code>where</code>、<code>order by</code>、<code>group by</code></li><li>聚合函数：<code>count</code>、<code>sum</code>、<code>avg</code>、<code>max</code>、<code>min</code></li><li><code>join</code> 的使用</li><li>子查询和分页</li></ul><p>至少要熟练：</p><ul><li>写出满足业务需求的查询</li><li>避免把所有数据查出来再在代码里过滤</li></ul><h3 id="_3-索引" tabindex="-1">3. 索引 <a class="header-anchor" href="#_3-索引" aria-label="Permalink to &quot;3. 索引&quot;">​</a></h3><ul><li>索引的作用和代价</li><li>B+ 树索引的基本思想</li><li>什么字段适合建索引</li><li>联合索引和最左匹配</li><li>为什么索引多了也会影响写入</li></ul><p>至少要理解：</p><ul><li>为什么一个查询突然变慢</li><li>为什么加了索引后仍然没有生效</li></ul><h3 id="_4-事务" tabindex="-1">4. 事务 <a class="header-anchor" href="#_4-事务" aria-label="Permalink to &quot;4. 事务&quot;">​</a></h3><ul><li>事务的基本概念</li><li>ACID 是什么</li><li>提交、回滚</li><li>脏读、不可重复读、幻读</li><li>隔离级别的大致区别</li></ul><p>至少要会用在：</p><ul><li>扣库存</li><li>支付状态更新</li><li>多表写入一致性</li></ul><h3 id="_5-锁与并发" tabindex="-1">5. 锁与并发 <a class="header-anchor" href="#_5-锁与并发" aria-label="Permalink to &quot;5. 锁与并发&quot;">​</a></h3><ul><li>行锁、表锁</li><li>乐观锁、悲观锁</li><li>死锁的基本原因</li><li>高并发更新同一条数据时会发生什么</li></ul><p>至少要理解：</p><ul><li>为什么接口有时会卡住</li><li>为什么明明 SQL 很简单却执行很慢</li></ul><h3 id="_6-执行计划与性能优化" tabindex="-1">6. 执行计划与性能优化 <a class="header-anchor" href="#_6-执行计划与性能优化" aria-label="Permalink to &quot;6. 执行计划与性能优化&quot;">​</a></h3><ul><li><code>explain</code> 的基本看法</li><li>全表扫描是什么</li><li>回表、覆盖索引基本概念</li><li>慢查询日志的用途</li><li>SQL 优化不是只靠“加索引”</li></ul><p>至少要能优化：</p><ul><li>列表分页查询</li><li>条件筛选查询</li><li>联表查询</li><li>统计类查询</li></ul><h3 id="_7-数据安全与恢复" tabindex="-1">7. 数据安全与恢复 <a class="header-anchor" href="#_7-数据安全与恢复" aria-label="Permalink to &quot;7. 数据安全与恢复&quot;">​</a></h3><ul><li>备份和恢复的基本流程</li><li>误删数据怎么办</li><li>迁移脚本如何管理</li><li>生产环境改表为什么要谨慎</li></ul><p>至少要有意识：</p><ul><li>任何重要数据都要能备份</li><li>任何结构变更都要可回滚或可补救</li></ul><h3 id="_8-缓存与数据库边界" tabindex="-1">8. 缓存与数据库边界 <a class="header-anchor" href="#_8-缓存与数据库边界" aria-label="Permalink to &quot;8. 缓存与数据库边界&quot;">​</a></h3><ul><li>什么适合放数据库，什么适合放缓存</li><li>Redis 不能替代关系型数据库</li><li>缓存穿透、击穿、雪崩了解概念即可</li></ul><p>至少要理解：</p><ul><li>为什么热点数据不能全靠数据库硬扛</li><li>为什么缓存和数据库会有一致性问题</li></ul><h2 id="作为前端转全栈的学习重点" tabindex="-1">作为前端转全栈的学习重点 <a class="header-anchor" href="#作为前端转全栈的学习重点" aria-label="Permalink to &quot;作为前端转全栈的学习重点&quot;">​</a></h2><h3 id="第一阶段" tabindex="-1">第一阶段 <a class="header-anchor" href="#第一阶段" aria-label="Permalink to &quot;第一阶段&quot;">​</a></h3><ul><li>先把 MySQL 或 PostgreSQL 用熟一个</li><li>能自己设计表结构</li><li>能独立写增删改查和常见联表 SQL</li></ul><h3 id="第二阶段" tabindex="-1">第二阶段 <a class="header-anchor" href="#第二阶段" aria-label="Permalink to &quot;第二阶段&quot;">​</a></h3><ul><li>掌握索引、事务、锁、执行计划</li><li>能对慢 SQL 做基础优化</li></ul><h3 id="第三阶段" tabindex="-1">第三阶段 <a class="header-anchor" href="#第三阶段" aria-label="Permalink to &quot;第三阶段&quot;">​</a></h3><ul><li>学会备份恢复、迁移管理、读写分离、缓存协同</li></ul><h2 id="推荐的实战场景" tabindex="-1">推荐的实战场景 <a class="header-anchor" href="#推荐的实战场景" aria-label="Permalink to &quot;推荐的实战场景&quot;">​</a></h2><ul><li>用户系统：注册、登录、会话、权限</li><li>内容系统：文章、标签、评论、分类</li><li>订单系统：下单、支付状态、库存扣减</li><li>订阅系统：会员、账单、回调记录</li><li>数据后台：搜索、筛选、分页、统计报表</li></ul><h2 id="判断自己是否掌握" tabindex="-1">判断自己是否掌握 <a class="header-anchor" href="#判断自己是否掌握" aria-label="Permalink to &quot;判断自己是否掌握&quot;">​</a></h2><ul><li>你能从业务需求出发表结构</li><li>你能写出正确且可维护的 SQL</li><li>你能解释索引为什么生效或失效</li><li>你能处理并发更新和事务一致性问题</li><li>你能对常见慢查询做出有效优化</li></ul>',46)])])}const b=i(r,[["render",t]]);export{_ as __pageData,b as default};
